// Duplicate detection check to ensure no race keys are duplicated across sources
function validateNoDuplicateRaces() {
  const seenKeys = new Set<string>();
  const duplicates: Array<{ key: string; name: string; index: number }> = [];

  GRADED_RACES.forEach((race, index) => {
    if (seenKeys.has(race.key)) {
      duplicates.push({ key: race.key, name: race.name, index });
    } else {
      seenKeys.add(race.key);
    }
  });

  if (duplicates.length > 0) {
    const duplicateList = duplicates
      .map((d) => `  - "${d.key}" (${d.name}) at index ${d.index}`)
      .join("\n");
    throw new Error(
      `Duplicate race keys found in GRADED_RACES:\n${duplicateList}\n` +
      `Each race must have a unique key. Please remove or rename the duplicates.`
    );
  }
}

// Run validation at module initialization
validateNoDuplicateRaces();
